WITH flattened AS (SELECT id, customer_id, created_at, tag FROM carts LATERAL VIEW OUTER EXPLODE(coupon_codes) li AS tag), with_dims AS (SELECT src.id, src.customer_id, c.city, c.name, c.age FROM flattened src INNER JOIN customers c ON src.customer_id <=> c.id WHERE c.city IN ('Berlin', 'Bangkok')), cleaned AS (SELECT id, customer_id, COALESCE(age, 0) age_filled, COALESCE(city, 'UNKNOWN') resolved_city FROM with_dims WHERE UPPER(TRIM(name)) = 'CAROL DIAZ'), base AS (SELECT *, ROUND(age_filled * 0.9, 2) age_filled_scaled, CASE WHEN age_filled >= 75 THEN 'High' WHEN age_filled >= 32 THEN 'Medium' ELSE 'Low' END age_filled_band FROM cleaned WHERE customer_id IS NOT NULL), enriched AS (SELECT e.id, e.customer_id, e.age_filled_scaled, c.age FROM base e LEFT JOIN customers c ON e.customer_id = c.id), joined AS (SELECT e.*, d.segment, d.email, d.name FROM enriched e LEFT JOIN customers d ON e.customer_id = d.id) SELECT s.id, s.customer_id, s.age_filled_scaled, s.segment, s.name, (SELECT MIN(t2.balance) FROM accounts t2 WHERE t2.customer_id = s.customer_id) AS min_account_balance FROM joined s ORDER BY segment NULLS FIRST, age_filled_scaled
